"""Pilot v2 intent table (DRAFT). One entry per intent; two paraphrases each.

Each paraphrase is six lines: (en_c, en_q, ta_c, ta_q, ml_c, ml_q) = English command, English polite question ("could you ..."),
Tanglish command, Tanglish polite question, Manglish command, Manglish polite question. The argument values (ids, amounts, paths,
emails, quoted text, names) are identical in all six lines of an intent and across its two paraphrases.
"""
def eq(v): return {"eq": v}
def num(v): return {"num": v}
def has(*s): return {"contains_all": list(s)}
def anyhas(*s): return {"contains_any": list(s)}
def path(v): return {"path": v}
def member(v): return {"list_has": v}
def req(tool, **a): return {"name": tool, "args": a}

